-- Generated by scripts/materials/build_seed.py --photo-migration photos-1101-https.
-- Queues product photo links for the mirror job. Every size of a model gets the
-- model's photos; a model that already has an image is skipped, so re-running
-- inserts nothing. The mirror allowlist is the set of hosts in this table, so
-- the new hosts join it with these rows.

WITH seed AS (
    SELECT * FROM jsonb_to_recordset($seed$[{"category":"kayak","brand":"Spade Kayaks","model":"Ace of Spades","variant":null,"size":null,"images":[{"url":"https://www.kayaksession.com/wp-content/uploads/2015/03/Ace0001.jpeg","page_url":"https://www.kayaksession.com/?p=89822","batch":"photos-1101-https"},{"url":"https://www.kayaksession.com/wp-content/uploads/2015/03/Ace0002.jpeg","page_url":"https://www.kayaksession.com/?p=89822","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"Alpina","variant":"660","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_alpina.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-alpina.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"Alpina","variant":"730","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_alpina.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-alpina.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"IV Down River","variant":"635","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_iv.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-iv-down-river.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"IV Down River","variant":"705","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_iv.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-iv-down-river.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"IV Down River","variant":"735","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_iv.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-iv-down-river.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"IV Down River","variant":"765","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_iv.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-iv-down-river.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"Slalom Sjoa","variant":"695","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_slalom_sjoa.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-slalom/braca-slalom-sjoa.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"Slalom Sjoa","variant":"725","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_slalom_sjoa.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-slalom/braca-slalom-sjoa.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"Slalom Soca","variant":"695","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_slalom_soca.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-slalom/braca-slalom-soca.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"Slalom Soca","variant":"735","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_slalom_soca.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-slalom/braca-slalom-soca.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"XI Van Dusen 92 Down River","variant":"705","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_xi.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-xi-van-dusen-down-river.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"XI Van Dusen 92 Down River","variant":"735","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_xi.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-xi-van-dusen-down-river.html","batch":"photos-1101-https"}]},{"category":"paddle","brand":"Braca","model":"XI Van Dusen 92 Down River","variant":"760","size":null,"images":[{"url":"https://paddles.braca-sport.com/images/paddles/braca_xi.png","page_url":"http://paddles.braca-sport.com/paddles/kayak-down-river/braca-xi-van-dusen-down-river.html","batch":"photos-1101-https"}]}]$seed$::jsonb) AS s(
        category material_category, brand text, model text, variant text, size text,
        images jsonb
    )
), target AS (
    SELECT m.id AS material_id, s.brand, s.images
    FROM seed s
    JOIN materials m ON m.category = s.category
        AND lower(btrim(m.brand)) = lower(btrim(s.brand))
        AND lower(btrim(m.model)) = lower(btrim(s.model))
        AND lower(btrim(COALESCE(m.variant, ''))) = lower(btrim(COALESCE(s.variant, '')))
        AND lower(btrim(COALESCE(m.size, ''))) = lower(btrim(COALESCE(s.size, '')))
        AND m.created_by = 'system-catalogue'
    WHERE NOT EXISTS (
        SELECT 1 FROM materials o
        JOIN material_images oi ON oi.material_id = o.id
        WHERE o.category = m.category
          AND lower(btrim(o.brand)) = lower(btrim(m.brand))
          AND lower(btrim(o.model)) = lower(btrim(m.model))
          AND lower(btrim(COALESCE(o.variant, ''))) = lower(btrim(COALESCE(m.variant, '')))
    )
)
INSERT INTO material_images (material_id, source_url, host, page_url, credit)
SELECT t.material_id, i->>'url', lower(substring(i->>'url' from '^https://([^/?#:@]+)')),
       i->>'page_url', t.brand
FROM target t
CROSS JOIN LATERAL jsonb_array_elements(t.images) AS i
ON CONFLICT (material_id, source_url) DO NOTHING;
